export interface CarouselNewProps extends HTMLAttributes<HTMLDivElement> {
    /**
     * Номер слайда.
     * Controlled-режим.
     */
    index?: number;
    /**
     * Callback для изменения слайда;
     */
    onChangeIndex?: (index: number) => void;
    /**
     * Номер слайда по-умолчанию.
     * Только при uncontrolled-режиме.
     * @default 0
     */
    defaultIndex?: number;
    /**
     * Центрирование активного элемента при скролле.
     * @default start
     */
    scrollAlign?: ScrollAlign;
    /**
     * Опции управления пагинацией.
     */
    paginationOptions?: {
        /**
         * Включение/выключение пагинации.
         * @default false
         */
        disabled?: boolean;
        /**
         * Количество видимых точек пагинации.
         * @default 10
         */
        visibleDots?: number;
        /**
         * Центрирование активной точки.
         * @default false
         */
        centered?: boolean;
    };
    /**
     * Включение/выключение стрелок управления слайдами.
     * @default false
     */
    controlArrowsDisabled?: boolean;
    /**
     * Отступ между слайдами.
     * @default 20px
     */
    gap?: CSSProperties['gap'];
    /**
     * Зацикливание карусели.
     * При включении после последнего слайда идет первый, и наоборот.
     * @default false
     */
    loop?: boolean;
    /**
     * Автоматическое пролистывание карусели.
     * @default false
     */
    autoPlay?: boolean;
    /**
     * Интервал автоматического пролистывания в мс.
     * @default 5000
     */
    autoPlayInterval?: number;
    /**
     * Включение свайпа/drag для touch- и pointer-устройств.
     * @default false
     */
    swipeEnabled?: boolean;
    /**
     * Включение виртуализации слайдов.
     * @default false
     */
    virtual?: boolean;

    /**
     * Размер контрола.
     */
    size?: string;
    /**
     * Вид контрола.
     * @default default
     */
    view?: string;
}
```

## Использование Использование `Carousel`  принимает набор React-элементов и отображает их как горизонтальную ленту с прокруткой. Обычно в компонент передают карточки одинаковой или близкой ширины, чтобы переход между слайдами выглядел предсказуемо. Для простого сценария достаточно передать элементы в  `children` . Если нужно задать стартовый слайд один раз при инициализации, используйте  `defaultIndex` . Если индексом нужно управлять снаружи, переключайте компонент в controlled-режим через  `index`  и  `onChangeIndex` . Для мобильных сценариев имеет смысл включать  `swipeEnabled` , а если внешние кнопки навигации не нужны, можно скрыть встроенные стрелки через  `controlArrowsDisabled` . ## Примеры Примеры ```tsx
import React from 'react';
import { Carousel } from '@salutejs/sdds-finai';
import styled from 'styled-components';

export function App() {
    const StyledCard = styled.div`
        display: flex;
        align-items: center;
        justify-content: center;
        border: 1px solid #d6d6d6;
        border-radius: 12px;
        width: 320px;
        height: 180px;
        background-color: #f4f5f7;
        color: #1b1f23;
        font-size: 20px;
        font-weight: 600;
    `;

    const items = Array(10).fill(0).map((_, i) => `Слайд ${i + 1}`);

    return (
        <div style={{ display: 'block', width: '500px' }}>
            <Carousel gap="16px">
                {items.map((item) => (
                    <StyledCard key={item}>{item}</StyledCard>
                ))}
            </Carousel>
        </div>
    );
}
```

